public class Issue72_second_highest_unique_score { public static void main(String[] args) { int[] v=new int[]{3, -11, 15, 2, 2}; int first=v[0], second=v[1]; for(int n:v) { if(n>first) { second=first; first=n; } else if(n>second && n!=first) second=n; } System.out.println("Second largest: "+first); } }
